// Regenerates src/components/site/AfricaMap.tsx — a single merged outline of the
// African continent (all 54 states + island nations), Mercator-projected, from
// Natural Earth 50m geodata (via the world-atlas package).
//
// The geo tooling (world-atlas, topojson-client, d3-geo) is NOT a runtime
// dependency — install it only to run this script, then remove it:
//   npm i -D world-atlas@2.0.2 topojson-client@3.1.0 d3-geo@3.1.1
//   node scripts/gen-africa.mjs
//   npm remove world-atlas topojson-client d3-geo
//
// Do not hand-edit the generated file; change this script and regenerate.

import { readFileSync, writeFileSync } from "node:fs";
import { merge } from "topojson-client";
import { geoMercator, geoPath } from "d3-geo";

const topo = JSON.parse(
  readFileSync(new URL("../node_modules/world-atlas/countries-50m.json", import.meta.url)),
);
const countries = topo.objects.countries;

// ISO 3166-1 numeric codes for African states (incl. island nations + W. Sahara)
const AFRICA = new Set([
  "012", "024", "204", "072", "854", "108", "120", "132", "140", "148", "174",
  "178", "180", "262", "818", "226", "232", "748", "231", "266", "270", "288",
  "324", "624", "384", "404", "426", "430", "434", "450", "454", "466", "478",
  "480", "504", "508", "516", "562", "566", "646", "678", "686", "690", "694",
  "706", "710", "728", "729", "834", "768", "788", "800", "732", "894", "716",
]);

const geoms = countries.geometries.filter((g) => AFRICA.has(String(g.id)));
console.error("matched African geometries:", geoms.length);
const merged = merge(topo, geoms); // single MultiPolygon of the continent

// Project (Mercator) and fit tightly into a width-600 box with small padding.
const W = 600;
const pad = 8;
const proj = geoMercator().scale(1).translate([0, 0]);
const b0 = geoPath(proj).bounds(merged);
const s = (W - 2 * pad) / (b0[1][0] - b0[0][0]);
const H = Math.round((b0[1][1] - b0[0][1]) * s + 2 * pad);
proj.scale(s).translate([
  (W - s * (b0[1][0] + b0[0][0])) / 2,
  (H - s * (b0[1][1] + b0[0][1])) / 2,
]);
let d = geoPath(proj)(merged);
d = d.replace(/-?\d+\.\d+/g, (n) => (+n).toFixed(1)); // round to 1dp to shrink
const viewBox = `0 0 ${W} ${H}`;
console.error("viewBox:", viewBox, "path length:", d.length);

const file = `// AUTO-GENERATED by scripts/gen-africa.mjs from Natural Earth 50m (world-atlas).
// Single merged outline of the African continent (all 54 states + island
// nations), Mercator-projected. Do not hand-edit; regenerate instead.

export const AFRICA_VIEWBOX = "${viewBox}";
export const AFRICA_PATH =
  "${d}";

/** Africa continent outline (decorative map used by the hero). */
export function AfricaMap({ className }: { className?: string }) {
  return (
    <svg viewBox={AFRICA_VIEWBOX} className={className} role="img" aria-label="Map of Africa">
      <path d={AFRICA_PATH} fill="currentColor" />
    </svg>
  );
}
`;
writeFileSync(new URL("../src/components/site/AfricaMap.tsx", import.meta.url), file);
console.error("wrote src/components/site/AfricaMap.tsx");
